    @SuppressWarnings("unchecked") private static net.minecraft.client.renderer.entity.state.AvatarRenderState avatar(Minecraft client){var renderer=(AvatarRenderer<net.minecraft.client.player.LocalPlayer>)(Object)client.getEntityRenderDispatcher().getRenderer(client.player);var state=renderer.createRenderState();renderer.extractRenderState(client.player,state,.5f);return state;}
    private static void verifyWearable(ClientGameTestContext c,boolean netherite){c.runOnClient(client->{var frame=((FabricRenderState)avatar(client)).getData(BacktankArmorLayer.BACKTANK);if(frame==null||frame.netherite()!=netherite||!frame.foil()||frame.body().mesh==null||frame.shaft().mesh==null||frame.cogs().mesh==null||frame.body().mesh.size()==0||frame.shaft().mesh.size()==0||frame.cogs().mesh.size()==0)throw new AssertionError("Actual equipped original foil tank must extract all three source native meshes");});}
    private static void verifyWorld(ClientGameTestContext c){c.runOnClient(client->{for(var pos:List.of(P,Q)){var source=(BacktankBlockEntity)client.level.getBlockEntity(pos);var state=(BacktankRenderer.State)client.getBlockEntityRenderDispatcher().tryExtractRenderState(source,.5f,null,false);if(state==null||state.cogs.mesh==null||state.shaft.mesh==null||state.cogs.mesh.size()==0||state.shaft.mesh.size()==0||!Float.isFinite(state.cogAngle)||!Float.isFinite(state.shaftAngle))throw new AssertionError("Original native backtank shaft/cogs snapshot incomplete");}});}
    private static ItemStack paid(Item item){var stack=new ItemStack(item);stack.set(DataComponents.CUSTOM_NAME,Component.literal(NAME));var data=new CompoundTag();data.putInt("finite_native_armor_receipt",73);stack.set(DataComponents.CUSTOM_DATA,CustomData.of(data));return stack;}
    private static boolean original(ItemStack stack){return stack.getCount()==1&&stack.getHoverName().getString().equals(NAME)&&stack.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag().getIntOr("finite_native_armor_receipt",0)==73;}
    private static ItemStack find(ServerPlayer player,Item item){for(int i=0;i<36;i++){var stack=player.getInventory().getItem(i);if(stack.is(item))return stack;}for(var slot:EquipmentSlot.values())if(slot.isArmor()&&player.getItemBySlot(slot).is(item))return player.getItemBySlot(slot);return ItemStack.EMPTY;}
    private static int total(ServerPlayer player,Item item){int total=0;for(int i=0;i<36;i++){var stack=player.getInventory().getItem(i);if(stack.is(item))total+=stack.getCount();}for(var slot:EquipmentSlot.values())if(slot.isArmor()&&player.getItemBySlot(slot).is(item))total+=player.getItemBySlot(slot).getCount();return total;}
    private static void pool(net.fabricmc.fabric.api.client.gametest.v1.context.TestServerContext server,BlockPos pos,String fluid){server.runCommand("fill "+(pos.getX()-1)+" 5 7 "+(pos.getX()+1)+" 8 9 "+fluid);}
