    private static void close(ClientGameTestContext c){c.getInput().pressKey(InputConstants.KEY_ESCAPE);c.waitFor(client->client.gui.screen()==null,200);}
    private static void equip(ClientGameTestContext c,TestSingleplayerContext w,Item item,EquipmentSlot slot){int index=c.computeOnClient(client->{for(int i=0;i<36;i++)if(client.player.getInventory().getItem(i).is(item))return i;throw new AssertionError("Original paid armor is absent from actual native inventory "+item);});click(c,index,true);c.waitFor(client->client.player.getItemBySlot(slot).is(item),200);await(c,w,level->actual(level).getItemBySlot(slot).is(item),200,"Physical native inventory shift click did not equip original "+item);}
    private static void remove(ClientGameTestContext c,TestSingleplayerContext w,EquipmentSlot slot){int index=Inventory.EQUIPMENT_SLOT_MAPPING.int2ObjectEntrySet().stream().filter(entry->entry.getValue()==slot).findFirst().orElseThrow().getIntKey();click(c,index,true);c.waitFor(client->client.player.getItemBySlot(slot).isEmpty(),200);await(c,w,level->actual(level).getItemBySlot(slot).isEmpty(),200,"Physical native inventory shift click did not remove original armor from "+slot);}
    private static void click(ClientGameTestContext c,int inventoryIndex,boolean shift){var at=c.computeOnClient(client->{var screen=(InventoryScreen)client.gui.screen();var origin=(com.simibubi.create.test.mixin.NativeContainerScreenAccessor)screen;var slot=screen.getMenu().slots.stream().filter(candidate->candidate.container==client.player.getInventory()&&candidate.getContainerSlot()==inventoryIndex).findFirst().orElseThrow();var window=client.getWindow();float x=origin.create$getLeft()+slot.x+8,y=origin.create$getTop()+slot.y+8;return new Vec2(x*window.getScreenWidth()/window.getGuiScaledWidth(),y*window.getScreenHeight()/window.getGuiScaledHeight());});c.getInput().setCursorPos(at.x,at.y);c.waitTicks(2);if(shift)c.getInput().holdKey(InputConstants.KEY_LSHIFT);try{if(shift){c.runOnClient(client->client.mouseHandler.onButton(client.getWindow().handle(),new net.minecraft.client.input.MouseButtonInfo(InputConstants.MOUSE_BUTTON_LEFT,InputConstants.MOD_SHIFT),InputConstants.PRESS));c.waitTicks(1);c.runOnClient(client->client.mouseHandler.onButton(client.getWindow().handle(),new net.minecraft.client.input.MouseButtonInfo(InputConstants.MOUSE_BUTTON_LEFT,InputConstants.MOD_SHIFT),InputConstants.RELEASE));}else c.getInput().pressMouse(InputConstants.MOUSE_BUTTON_LEFT);}finally{if(shift)c.getInput().releaseKey(InputConstants.KEY_LSHIFT);}}
    private static void use(ClientGameTestContext c,BlockPos pos,Vec3 target,Direction side){look(c,target);c.waitFor(client->client.hitResult instanceof BlockHitResult hit&&hit.getBlockPos().equals(pos)&&hit.getDirection()==side,250);c.getInput().pressKey(options->options.keyUse);}
    private static void select(ClientGameTestContext c,TestSingleplayerContext w,int key,int slot){c.getInput().pressKey(key);c.waitFor(client->client.player.getInventory().getSelectedSlot()==slot,200);await(c,w,level->actual(level).getInventory().getSelectedSlot()==slot,200,"Physical native hotbar selection was not acknowledged");}
    private static void stand(ClientGameTestContext c,TestSingleplayerContext w,double x,double z){w.getServer().runCommand("gamemode survival @p");w.getServer().runCommand("tp @p "+x+" 5 "+z);c.waitFor(client->!client.player.isSpectator()&&client.player.onGround()&&Math.abs(client.player.getX()-x)<.1&&Math.abs(client.player.getZ()-z)<.1,250);}
    private static void look(ClientGameTestContext c,Vec3 target){var angles=c.computeOnClient(client->{var delta=target.subtract(client.player.getEyePosition());return new Vec2((float)Math.toDegrees(Math.atan2(-delta.x,delta.z)),(float)-Math.toDegrees(Math.atan2(delta.y,Math.hypot(delta.x,delta.z))));});c.getInput().lookAt(angles.x,angles.y);}
    private static BacktankBlockEntity tank(ServerLevel level,BlockPos pos){return LoadedLevelAccess.blockEntity(level,pos) instanceof BacktankBlockEntity tank?tank:null;}
    private static ServerPlayer actual(ServerLevel level){return level.getServer().getPlayerList().getPlayers().getFirst();}
    private static void await(ClientGameTestContext c,TestSingleplayerContext w,Predicate<ServerLevel> predicate,int ticks,String failure){var done=new AtomicBoolean();for(int tick=0;tick<ticks;tick++){w.getServer().runOnServer(ignored->done.set(predicate.test(w.getConnection().getServerLevel())));if(done.get())return;c.waitTicks(1);}throw new AssertionError(failure);}
    private static void screenshot(ClientGameTestContext c,TestSingleplayerContext w,String name,String expected){c.waitFor(client->client.gui.overlay()==null,250);NativeScreenshotReadiness.await(c,w);c.runOnClient(client->{client.gui.hud.getChat().clearMessages(false);ArmorNativeRenderProbe.begin(name,expected);});try{c.takeScreenshot(name);}finally{c.runOnClient(client->ArmorNativeRenderProbe.end());}}
